// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.List;
import java.util.Map;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.EmptySet;
import org.eclipse.rdf4j.query.algebra.Filter;
import org.eclipse.rdf4j.query.algebra.Graph;
import org.eclipse.rdf4j.query.algebra.IsLiteral;
import org.eclipse.rdf4j.query.algebra.Service;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.PlanningGraphDomain;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.PlanningGraphDomains;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.OptimizationGoal;
import org.eclipse.rdf4j.query.algebra.helpers.AbstractQueryModelVisitor;
import org.junit.jupiter.api.Test;

class PackedPredicateRangeApplicabilityTest {

	private static final SimpleValueFactory VALUES = SimpleValueFactory.getInstance();
	private static final PackedPredicateRangeProvider CONSERVATIVE = rangeProvider(false);
	private static final PackedPredicateRangeProvider UNIVERSAL = rangeProvider(true);

	@Test
	void currentSourceRangesRequireProvedEntryAndDoNotEnterActiveOrDetachedDomains() {
		for (TupleExpr source : new TupleExpr[] { contradiction(), selectedGraph() }) {
			assertFalse(containsEmpty(optimize(source, CONSERVATIVE)),
					"An unproved fragment or active graph must not inherit a source-domain guarantee");
		}
		TupleExpr proved = contradiction();
		PlanningGraphDomains.capture(proved, PlanningGraphDomain.defaultGraph());
		assertTrue(containsEmpty(optimize(proved, CONSERVATIVE)),
				"The backward-compatible default remains usable at a genuinely proved query entry");
	}

	@Test
	void sameSnapshotAllQuadRangesRemainValidForActiveAndUnprovedSubsets() {
		for (TupleExpr source : new TupleExpr[] { contradiction(), selectedGraph() }) {
			assertTrue(containsEmpty(optimize(source, UNIVERSAL)),
					"A universal RDF-kind guarantee applies to every selected graph subset");
		}
	}

	@Test
	void universalLocalRangesNeverAuthorizeRemoteServiceFacts() {
		Service remote = new Service(Var.of("endpoint", VALUES.createIRI("urn:range:remote")), selectedGraph(),
				"GRAPH <urn:range:graph> { ?s <urn:range:p> ?o FILTER(isLiteral(?o)) }", Map.of(), null, false);
		PlanningGraphDomains.capture(remote, PlanningGraphDomain.defaultGraph());
		assertFalse(containsEmpty(optimize(remote, UNIVERSAL)),
				"All-quads means the admitted local store, without authority over a remote SERVICE");
	}

	@Test
	void sameVersionCapabilityPartitionsExactFamilyAndConcreteRecipeAuthentication() {
		TupleExpr source = selectedGraph();
		assertEquals(CONSERVATIVE.predicateRangeVersion(), UNIVERSAL.predicateRangeVersion());
		PackedQueryCacheIdentity conservative = PackedQueryCacheIdentity.createPlanIdentity(source, CONSERVATIVE);
		PackedQueryCacheIdentity universal = PackedQueryCacheIdentity.createPlanIdentity(source, UNIVERSAL);
		assertNotNull(conservative);
		assertNotNull(universal);
		assertFalse(conservative.matches(universal));
		assertTrue(universal.matches(PackedQueryCacheIdentity.createPlanIdentity(source.clone(), UNIVERSAL)));
		PackedPlanCache cache = new PackedPlanCache(16, 1);
		assertEquals(cache.fingerprint(source, conservative), cache.fingerprint(source, universal),
				"Routing deliberately permits same-shape collisions; the complete identity authenticates every hit");
		PackedQueryFamilyIdentity conservativeFamily = PackedQueryFamilyIdentity.create(source, CONSERVATIVE);
		PackedQueryFamilyIdentity universalFamily = PackedQueryFamilyIdentity.create(source, UNIVERSAL);
		assertNotNull(conservativeFamily);
		assertNotNull(universalFamily);
		assertFalse(conservativeFamily.matches(universalFamily));
		assertFalse(PackedQueryFamilyIdentity.sameConcreteInvocation(conservativeFamily, universalFamily));
		assertFalse(conservativeFamily.parameterizedQueryTemplate()
				.hasSameCacheIdentity(universalFamily.parameterizedQueryTemplate()));
		assertTrue(universalFamily.detached().matches(PackedQueryFamilyIdentity.create(source.clone(), UNIVERSAL)));
		PackedPlanCache.Context context = new PackedPlanCache.Context(1L, 2L, 3L, 4L, 5L, 6L, 7L,
				UNIVERSAL.predicateRangeVersion());
		for (boolean universalFirst : List.of(false, true)) {
			PackedPlanCache collisionCache = new PackedPlanCache(16, 1);
			int invocation = 0;
			for (boolean universalProof : List.of(universalFirst, !universalFirst, universalFirst, !universalFirst)) {
				PackedPlanningResult result = PackedCascadesPlanner.optimize(source.clone(),
						OptimizationGoal.root(source, null), collisionCache, context, null,
						universalProof ? UNIVERSAL : CONSERVATIVE);
				assertEquals(universalProof, containsEmpty(result.selectedPlan()),
						"Same routing and version must retain current capability, universal=" + universalProof
								+ ", universalFirst=" + universalFirst);
				assertEquals(invocation++ >= 2, result.metrics().planCacheHit(),
						"Distinct authority must miss initially and reuse its own authenticated plan on repetition");
			}
		}
	}

	private static TupleExpr optimize(TupleExpr source, PackedPredicateRangeProvider provider) {
		return PackedCascadesPlanner.optimize(source, OptimizationGoal.root(source, null).asBudgeted(null, 1_000_000),
				null, provider).selectedPlan();
	}

	private static Graph selectedGraph() {
		return new Graph(Var.of("graph", VALUES.createIRI("urn:range:graph")), contradiction());
	}

	private static Filter contradiction() {
		return new Filter(new StatementPattern(Var.of("s"), Var.of("p", VALUES.createIRI("urn:range:p")), Var.of("o")),
				new IsLiteral(Var.of("o")));
	}

	private static boolean containsEmpty(TupleExpr source) {
		boolean[] found = { false };
		source.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(EmptySet empty) {
				found[0] = true;
			}
		});
		return found[0];
	}

	private static PackedPredicateRangeProvider rangeProvider(boolean universal) {
		return new PackedPredicateRangeProvider() {
			@Override
			public boolean describeObjectRange(IRI predicate, PackedPredicateRange output) {
				output.setState(PackedPredicateRange.STATE_KNOWN);
				output.setKindBits(PackedPredicateRange.KIND_IRI);
				return true;
			}

			@Override
			public long predicateRangeVersion() {
				return 1L;
			}

			@Override
			public RangeApplicability predicateRangeApplicability() {
				return universal ? RangeApplicability.ALL_QUADS : RangeApplicability.CURRENT_DOMAIN;
			}
		};
	}
}
